insert into public.biblical_concordance_terms (
  canonical_term, normalized_term, language, description, source_id,
  source_locator, provider_version, content_hash, review_status, enabled, metadata
)
select
  d.canonical_term, d.normalized_term, 'es', d.description, s.id,
  d.source_locator, 'concordance-rich-v1-2026-08-02', encode(digest(d.content_hash, 'sha256'), 'hex'),
  'approved', true,
  jsonb_build_object('editorial_scope', 'tema_biblico', 'generated_by_ai', false, 'catalog_version', 'rich-v1')
from dataset d
cross join source s
on conflict (normalized_term, language, source_id)
do update set
  canonical_term = excluded.canonical_term,
  description = excluded.description,
  source_locator = excluded.source_locator,
  provider_version = excluded.provider_version,
  content_hash = excluded.content_hash,
  review_status = 'approved',
  enabled = true,
  metadata = excluded.metadata,
  updated_at = now();

