)
insert into public.biblical_concordance_occurrences(term_id,book_code,book_name,chapter,verse,reference_label,relevance,relation_kind,source_id,source_locator,provider_version,content_hash,review_status,enabled,metadata)
select term_id,book_code,book_name,chapter,verse,reference_label,relevance,relation_kind,source_id,
'editorial-reference:'||lower(book_code)||':'||chapter||':'||verse,'concordance-rich-v1-2026-08-02',
encode(digest(normalized_term||':'||book_code||':'||chapter||':'||verse||':'||relation_kind,'sha256'),'hex'),'approved',true,
jsonb_build_object('editorial_relation',true,'generated_by_ai',false,'catalog_version','rich-v1')
from resolved
on conflict(term_id,book_code,chapter,verse,relation_kind,source_id) do update set
book_name=excluded.book_name,reference_label=excluded.reference_label,relevance=excluded.relevance,source_locator=excluded.source_locator,provider_version=excluded.provider_version,content_hash=excluded.content_hash,review_status='approved',enabled=true,metadata=excluded.metadata,updated_at=now();
